def materialize(directory: Path, *names: str) -> dict[str, Path]:
    """Write the named private-key fixtures into *directory* as real PEM files.

    With no names, every fixture is written. Returns name -> path.
    """
    selected = names or tuple(PRIVATE_KEYS)
    written: dict[str, Path] = {}
    for name in selected:
        _, payload = PRIVATE_KEYS[name]
        target = directory / name
        target.write_bytes(base64.b64decode(payload))
        written[name] = target
    return written
